    storyTitleEm: "Una visión.",
    storyTitleHtml: "Más que una agencia de viajes<br>. <em>A Visión.</em>",
    storyBody: "Basado en la creencia de que cada viajero merece una experiencia verdaderamente personal: no un paquete, no una plantilla, sino un viaje diseñado completamente en torno a usted.",
    planJourney: "Planifica tu viaje",
