    whoTitle1: "Pasión por viajar",
    whoTitleEm: "en Nuestro ADN",
    whoTitleHtml: "Pasión por viajar<br><em>en nuestro ADN</em>",
    whoP1: "Martins Global Travels nació de una única creencia: que viajar, bien hecho, tiene el poder de cambiar vidas. Nuestro fundador, Martins, pasó años explorando los mejores destinos del mundo y creó esta agencia para compartir esa sensación de asombro, con la comodidad y precisión que merecen los viajeros modernos.",
    whoP2: "Nuestro equipo de diseñadores de viajes especializados siente pasión por cada destino que ofrecemos. Cada persona explora personalmente los lugares que recomienda; nunca sugerimos ningún lugar que no hayamos experimentado de primera mano.",
    whoP3: "Desde seleccionar meticulosamente el hotel perfecto hasta brindarle asistencia en tiempo real mientras está de viaje, todo lo que hacemos está guiado por una pregunta: ¿qué haría de este el viaje más extraordinario de su vida?",
    pillarVision: "Visión",
