    val2t: "Excelencia implacable",
    val2d: "Cada hotel inspeccionado, cada guía capacitado, cada itinerario sometido a pruebas de estrés antes de recomendarlo a un solo cliente.",
    val3t: "Viaje responsable",
    val3d: "Seleccionamos cuidadosamente operadores responsables y estamos comprometidos con prácticas de viaje éticas y sostenibles en cada destino.",
    val4t: "Transparencia total",
