    whoP3: "Soti nan seleksyon metikuleu otèl la pafè a bay sipò an tan reyèl pandan w ap sou wout la - tout sa nou fè se gide pa yon sèl kesyon: ki sa ki ta fè vwayaj sa a pi ekstraòdinè nan lavi ou?",
