    whoTitleHtml: "Paixão por Viajar<br><em>em Nosso DNA</em>",
    whoP1: "A Martins Global Travels nasceu de uma única crença: que viajar, quando bem feito, tem o poder de mudar vidas. Nosso fundador, Martins, passou anos explorando os melhores destinos do mundo e construiu esta agência para compartilhar esse sentimento de admiração — com o conforto e a precisão que os viajantes modernos merecem.",
    whoP2: "Nossa equipe de designers de viagens especializados é apaixonada por cada destino que oferecemos. Cada pessoa explora pessoalmente os lugares que recomenda – nunca sugerimos nenhum lugar que não tenhamos experimentado em primeira mão.",
    whoP3: "Desde a seleção meticulosa do hotel perfeito até o fornecimento de suporte em tempo real enquanto você está na estrada – tudo o que fazemos é guiado por uma pergunta: o que tornaria esta viagem a mais extraordinária da sua vida?",
